import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useScopedControl,controlIdentity,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {Pressable,Text,View,type ViewProps} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {keyboardKey,type KeyEventLike} from "@/components/nyc-tron/ui/components/gestures/drag-transport";
import {Glyph,type TransportGlyph} from "@/components/nyc-tron/ui/components/forge/timeline/glyphs";
import {space,opacity,size} from '@/components/nyc-tron/ui/tokens';

/** Props for {@linkcode TransportControls}. */
export interface TransportControlsProps extends Omit<ViewProps,"children">,ScopedControlProps {
  /** What the player reports, not what was last requested. */
  readonly playing:boolean;
  readonly frame:number;
  readonly durationFrames:number;
  readonly onPlayPause:()=>void;
  /** Stop: pause and return to the start (or the in mark; the host decides). */
  readonly onStop:()=>void;
  /** Jumps and frame steps. One call per press. */
  readonly onSeek:(frame:number)=>void;
  /** Disables every control and is read out as the reason, e.g. "No media loaded". */
  readonly disabledReason?:string;
  className?:string;
  unstyled?:boolean;
}

/**
 * Play/pause, stop, jump to start/end and previous/next frame (D-06), each a
 * 44pt button. With focus inside, K toggles playback, Left/Right step
 * a frame and Home/End jump. Frame steps stop at the timeline's ends. Playback
 * itself (decoding, the clock) belongs to the host's player.
 */
export function TransportControls({scope='TransportControls',revision=0,...props}:TransportControlsProps){
 const owner=JSON.stringify([...controlIdentity(scope,revision),props.disabledReason,props.durationFrames]);
 const guard=useScopedControl(owner,props,props.disabledReason!==undefined);
 return <TransportControlsBody key={owner} {...props} actionError={guard.error} {...(guard.pending?{disabledReason:'Operation in progress'}:{})}
  onPlayPause={()=>guard.run('onPlayPause',host=>host.onPlayPause())}
  onStop={()=>guard.run('onStop',host=>host.onStop())}
  onSeek={(value)=>guard.run('onSeek',host=>host.onSeek(value))}/>;
}
function TransportControlsBody({
  actionError=null,
  playing,frame,durationFrames,onPlayPause,onStop,onSeek,disabledReason,className,unstyled=false,testID,style,...rest
}:TransportControlsProps&{actionError?:string|null}){
  if(!Number.isSafeInteger(frame)||frame<0||!Number.isSafeInteger(durationFrames)||durationFrames<0)throw new RangeError("durationFrames must be a nonnegative integer");
  const off=disabledReason!==undefined||durationFrames===0;
  const styled=!unstyled;
  const f=Math.min(durationFrames,Math.max(0,Math.round(frame)));
  const seek=(n:number)=>{const t=Math.min(durationFrames,Math.max(0,n));if(!off&&t!==f)onSeek(t);};
  const button=(glyph:TransportGlyph,label:string,onPress:()=>void,disabled=false,primary=false)=>
    <Pressable key={primary?"play-pause":glyph} accessibilityRole="button" accessibilityLabel={label}
      accessibilityState={{disabled:off||disabled}} disabled={off||disabled} onPress={onPress}
      {...(testID?{testID:testID+"-"+glyph}:{})}
      {...{className:joinClasses(styled&&"rounded-control border focus-visible:ring-2 focus-visible:ring-focus",
        styled&&(primary?"border-border bg-surface-sunken":"border-transparent"))}}
      style={{minWidth:primary?56:size.touch,minHeight:size.touch,alignItems:"center",justifyContent:"center",opacity:off||disabled?opacity[40]:1}}>
      <Glyph name={glyph} styled={styled}/>
    </Pressable>;
  const onKeyDown=(event:KeyEventLike)=>{
    if(off)return;
    const key=keyboardKey(event);
    // Space is left to the focused button; K toggles playback from anywhere in the bar.
    const act=key==="k"||key==="K"?onPlayPause
      :key==="ArrowLeft"?()=>seek(f-1):key==="ArrowRight"?()=>seek(f+1)
      :key==="Home"?()=>seek(0):key==="End"?()=>seek(durationFrames):undefined;
    if(!act)return;
    (event as {preventDefault?:()=>void}).preventDefault?.();
    act();
  };
  return <View {...rest} {...(testID?{testID}:{})} {...{onKeyDown}}
    accessibilityRole="toolbar" accessibilityLabel="Transport"
    {...{className:joinClasses("gap-1",className)}}
    // Media controls are not mirrored in right-to-left layouts (Material and Apple guidance):
    // they describe tape direction, not reading order.
    style={[{flexDirection:"row",alignItems:"center",flexWrap:"wrap",direction:"ltr"},style]}>
    <ErrorMessage message={actionError??undefined} unstyled={unstyled}/>
    {button("start","Go to start",()=>seek(0),f===0)}
    {button("previous-frame","Previous frame",()=>seek(f-1),f===0)}
    {button(playing?"pause":"play",playing?"Pause":"Play",onPlayPause,false,true)}
    {button("next-frame","Next frame",()=>seek(f+1),f>=durationFrames)}
    {button("end","Go to end",()=>seek(durationFrames),f>=durationFrames)}
    {button("stop","Stop",onStop)}
    {disabledReason?<Text {...{className:joinClasses(styled&&"text-text-muted text-sm")}} style={{paddingHorizontal:space[1.5]}}>{disabledReason}</Text>:null}
  </View>;
}

import {View} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {space} from "@/components/nyc-tron/ui/tokens";

/** Transport glyphs drawn from views (no icon dependency) so they take the text token in both themes and in forced colors. */
export type TransportGlyph="play"|"pause"|"stop"|"start"|"end"|"previous-frame"|"next-frame";

const triangle=(dir:"right"|"left",size:number,cls:string)=>
  <View {...{className:cls}} style={{width:0,height:0,borderTopWidth:size/2,borderBottomWidth:size/2,
    borderTopColor:"transparent",borderBottomColor:"transparent",
    ...(dir==="right"?{borderLeftWidth:size*0.85}:{borderRightWidth:size*0.85})}}/>;
const bar=(w:number,h:number,cls:string)=><View {...{className:cls}} style={{width:w,height:h}}/>;

/**
 * One transport glyph, 16 units tall. `styled` false leaves the ink to the
 * app's classes on the parent. Triangles are drawn with borders: the
 * transparent sides are geometry, not color.
 */
export function Glyph({name,styled=true}:{name:TransportGlyph;styled?:boolean}){
  const fill=joinClasses(styled&&"bg-text");
  const left=joinClasses(styled&&"border-l-text");
  const right=joinClasses(styled&&"border-r-text");
  const row={flexDirection:"row" as const,alignItems:"center" as const,gap:space[0.25],direction:"ltr" as const};
  switch(name){
    case "play":return triangle("right",16,left);
    case "pause":return <View style={{...row,gap:space[1]}}>{bar(4,15,fill)}{bar(4,15,fill)}</View>;
    case "stop":return bar(13,13,fill);
    case "start":return <View style={row}>{bar(2,14,fill)}{triangle("left",14,right)}</View>;
    case "end":return <View style={row}>{triangle("right",14,left)}{bar(2,14,fill)}</View>;
    case "previous-frame":return <View style={row}>{triangle("left",12,right)}{bar(2,12,fill)}</View>;
    case "next-frame":return <View style={row}>{bar(2,12,fill)}{triangle("right",12,left)}</View>;
  }
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

